  // Onboarding
  "onboarding.loading": { en: "Loading…", hi: "लोड हो रहा है…", bn: "লোড হচ্ছে…", mr: "लोड होत आहे…", te: "లోడ్ అవుతోంది…", ta: "ஏற்றுகிறது…", gu: "લોડ થઈ રહ્યું છે…", ur: "لوڈ ہو رہا ہے…", kn: "ಲೋಡ್ ಆಗುತ್ತಿದೆ…", or: "ଲୋଡ ହେଉଛି…", ml: "ലോഡ് ചെയ്യുന്നു…" },
  "onboarding.eyebrow": { en: "One more step", hi: "एक और कदम", bn: "আরও একটি ধাপ", mr: "आणखी एक पायरी", te: "మరో అడుగు", ta: "இன்னும் ஒரு படி", gu: "એક વધુ પગલું", ur: "ایک اور قدم", kn: "ಇನ್ನೊಂದು ಹೆಜ್ಜೆ", or: "ଆଉ ଏକ ପାହାଚ", ml: "ഒരു ചുവട് കൂടി" },
  "onboarding.title": { en: "Tell us about yourself", hi: "अपने बारे में बताएं", bn: "আপনার সম্পর্কে বলুন", mr: "आपल्याबद्दल सांगा", te: "మీ గురించి చెప్పండి", ta: "உங்களைப் பற்றி சொல்லுங்கள்", gu: "તમારા વિશે જણાવો", ur: "اپنے بارے میں بتائیں", kn: "ನಿಮ್ಮ ಬಗ್ಗೆ ಹೇಳಿ", or: "ନିଜ ବିଷୟରେ କୁହନ୍ତୁ", ml: "നിങ്ങളെക്കുറിച്ച് പറയൂ" },
  "onboarding.subtitle": { en: "This is what makes your dashboard actually yours, not a demo record.", hi: "यही आपके डैशबोर्ड को असल में आपका बनाता है, डेमो रिकॉर्ड नहीं।", bn: "এটাই আপনার ড্যাশবোর্ডকে সত্যিকারের আপনার করে তোলে, ডেমো রেকর্ড নয়।", mr: "यामुळेच तुमचे डॅशबोर्ड खरोखर तुमचे बनते, डेमो नोंद नाही.", te: "ఇది మీ డాష్‌బోర్డ్‌ను నిజంగా మీదిగా చేస్తుంది, డెమో రికార్డ్ కాదు.", ta: "இதுவே உங்கள் டாஷ்போர்டை உண்மையில் உங்களுடையதாக ஆக்குகிறது, டெமோ பதிவு அல்ல.", gu: "આ જ તમારા ડેશબોર્ડને ખરેખર તમારું બનાવે છે, ડેમો રેકોર્ડ નહીં.", ur: "یہی چیز آپ کے ڈیش بورڈ کو حقیقی معنوں میں آپ کا بناتی ہے، ڈیمو ریکارڈ نہیں۔", kn: "ಇದೇ ನಿಮ್ಮ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಅನ್ನು ನಿಜವಾಗಿಯೂ ನಿಮ್ಮದಾಗಿ ಮಾಡುತ್ತದೆ, ಡೆಮೊ ದಾಖಲೆಯಲ್ಲ.", or: "ଏହା ହିଁ ଆପଣଙ୍କ ଡ୍ୟାସବୋର୍ଡକୁ ପ୍ରକୃତରେ ଆପଣଙ୍କର କରିଥାଏ, ଡେମୋ ରେକର୍ଡ ନୁହେଁ।", ml: "ഇതാണ് നിങ്ങളുടെ ഡാഷ്‌ബോർഡിനെ യഥാർത്ഥത്തിൽ നിങ്ങളുടേതാക്കുന്നത്, ഡെമോ രേഖയല്ല." },
