  "settings.logout.description": { en: "You'll need to sign in again to access your account.", hi: "अपने खाते तक पहुंचने के लिए आपको फिर से साइन इन करना होगा।", bn: "আপনার অ্যাকাউন্ট অ্যাক্সেস করতে আবার সাইন ইন করতে হবে।", mr: "तुमच्या खात्यात प्रवेश करण्यासाठी तुम्हाला पुन्हा साइन इन करावे लागेल.", te: "మీ ఖాతాను యాక్సెస్ చేయడానికి మీరు మళ్లీ సైన్ ఇన్ చేయాలి.", ta: "உங்கள் கணக்கை அணுக மீண்டும் உள்நுழைய வேண்டும்.", gu: "તમારા ખાતામાં પ્રવેશવા માટે તમારે ફરીથી સાઇન ઇન કરવું પડશે.", ur: "اپنے اکاؤنٹ تک رسائی کے لیے آپ کو دوبارہ سائن ان کرنا ہوگا۔", kn: "ನಿಮ್ಮ ಖಾತೆಯನ್ನು ಪ್ರವೇಶಿಸಲು ನೀವು ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಬೇಕಾಗುತ್ತದೆ.", or: "ଆପଣଙ୍କ ଖାତାରେ ପ୍ରବେଶ କରିବାକୁ ପୁନର୍ବାର ସାଇନ ଇନ କରିବାକୁ ପଡିବ।", ml: "നിങ്ങളുടെ അക്കൗണ്ട് ആക്‌സസ് ചെയ്യാൻ വീണ്ടും സൈൻ ഇൻ ചെയ്യേണ്ടിവരും." },
  "settings.toast.profileUpdated": { en: "Profile updated", hi: "प्रोफ़ाइल अपडेट हुई", bn: "প্রোফাইল আপডেট হয়েছে", mr: "प्रोफाइल अपडेट झाली", te: "ప్రొఫైల్ అప్‌డేట్ చేయబడింది", ta: "சுயவிவரம் புதுப்பிக்கப்பட்டது", gu: "પ્રોફાઇલ અપડેટ થઈ", ur: "پروفائل اپ ڈیٹ ہوگئی", kn: "ಪ್ರೊಫೈಲ್ ನವೀಕರಿಸಲಾಗಿದೆ", or: "ପ୍ରୋଫାଇଲ ଅପଡେଟ ହେଲା", ml: "പ്രൊഫൈൽ അപ്ഡേറ്റ് ചെയ്തു" },
  "settings.toast.fillPasswords": { en: "Fill in your current and new password.", hi: "अपना वर्तमान और नया पासवर्ड भरें।", bn: "আপনার বর্তমান এবং নতুন পাসওয়ার্ড পূরণ করুন।", mr: "तुमचा सध्याचा आणि नवीन पासवर्ड भरा.", te: "మీ ప్రస్తుత మరియు కొత్త పాస్‌వర్డ్‌ను నింపండి.", ta: "உங்கள் தற்போதைய மற்றும் புதிய கடவுச்சொல்லை நிரப்பவும்.", gu: "તમારો વર્તમાન અને નવો પાસવર્ડ ભરો.", ur: "اپنا موجودہ اور نیا پاس ورڈ درج کریں۔", kn: "ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಮತ್ತು ಹೊಸ ಪಾಸ್‌ವರ್ಡ್ ಅನ್ನು ಭರ್ತಿ ಮಾಡಿ.", or: "ଆପଣଙ୍କ ବର୍ତ୍ତମାନ ଏବଂ ନୂଆ ପାସୱାର୍ଡ ପୂରଣ କରନ୍ତୁ।", ml: "നിങ്ങളുടെ നിലവിലെയും പുതിയതുമായ പാസ്‌വേഡ് പൂരിപ്പിക്കുക." },
  "settings.toast.passwordTooShort": { en: "New password needs at least 6 characters.", hi: "नए पासवर्ड में कम से कम 6 अक्षर होने चाहिए।", bn: "নতুন পাসওয়ার্ডে অন্তত ৬টি অক্ষর প্রয়োজন।", mr: "नवीन पासवर्डमध्ये किमान ६ अक्षरे असावीत.", te: "కొత్త పాస్‌వర్డ్‌కు కనీసం 6 అక్షరాలు అవసరం.", ta: "புதிய கடவுச்சொல்லில் குறைந்தது 6 எழுத்துகள் தேவை.", gu: "નવા પાસવર્ડમાં ઓછામાં ઓછા 6 અક્ષરો જોઈએ.", ur: "نئے پاس ورڈ میں کم از کم 6 حروف ہونے چاہئیں۔", kn: "ಹೊಸ ಪಾಸ್‌ವರ್ಡ್‌ಗೆ ಕನಿಷ್ಠ 6 ಅಕ್ಷರಗಳು ಬೇಕು.", or: "ନୂଆ ପାସୱାର୍ଡରେ ଅତିକମରେ 6ଟି ଅକ୍ଷର ଥିବା ଆବଶ୍ୟକ।", ml: "പുതിയ പാസ്‌വേഡിന് കുറഞ്ഞത് 6 അക്ഷരങ്ങൾ വേണം." },
  "settings.toast.passwordMismatch": { en: "New passwords don't match.", hi: "नए पासवर्ड मेल नहीं खाते।", bn: "নতুন পাসওয়ার্ড মেলে না।", mr: "नवीन पासवर्ड जुळत नाहीत.", te: "కొత్త పాస్‌వర్డ్‌లు సరిపోలలేదు.", ta: "புதிய கடவுச்சொற்கள் பொருந்தவில்லை.", gu: "નવા પાસવર્ડ મેળ ખાતા નથી.", ur: "نئے پاس ورڈ مماثل نہیں ہیں۔", kn: "ಹೊಸ ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಹೊಂದಿಕೆಯಾಗುತ್ತಿಲ್ಲ.", or: "ନୂଆ ପାସୱାର୍ଡ ମେଳ ଖାଉନାହିଁ।", ml: "പുതിയ പാസ്‌വേഡുകൾ പൊരുത്തപ്പെടുന്നില്ല." },
