  "lab.card.reportsRegisteredBy": { en: "Reports registered by", hi: "द्वारा पंजीकृत रिपोर्टें", bn: "দ্বারা নিবন্ধিত রিপোর্ট", mr: "यांनी नोंदवलेले अहवाल", te: "వీరిచే నమోదు చేయబడిన నివేదికలు", ta: "இவரால் பதிவு செய்யப்பட்ட அறிக்கைகள்", gu: "દ્વારા નોંધાયેલા અહેવાલો", ur: "کی طرف سے رجسٹرڈ رپورٹس", kn: "ಇವರಿಂದ ನೋಂದಾಯಿಸಲಾದ ವರದಿಗಳು", or: "ଦ୍ୱାରା ପଞ୍ଜୀକୃତ ରିପୋର୍ଟ", ml: "ഇവർ രജിസ്റ്റർ ചെയ്ത റിപ്പോർട്ടുകൾ" },
  "lab.empty.noReports": { en: "Nothing registered yet. Submit your first report on the left.", hi: "अभी तक कुछ पंजीकृत नहीं हुआ। बाईं ओर अपनी पहली रिपोर्ट जमा करें।", bn: "এখনো কিছু নিবন্ধিত হয়নি। বাম দিকে আপনার প্রথম রিপোর্ট জমা দিন।", mr: "अजून काहीही नोंदवलेले नाही. डावीकडे तुमचा पहिला अहवाल सादर करा.", te: "ఇంకా ఏమీ నమోదు కాలేదు. ఎడమ వైపు మీ మొదటి నివేదికను సమర్పించండి.", ta: "இன்னும் எதுவும் பதிவு செய்யப்படவில்லை. இடதுபுறத்தில் உங்கள் முதல் அறிக்கையை சமர்ப்பிக்கவும்.", gu: "હજુ સુધી કંઈ નોંધાયું નથી. ડાબી બાજુ તમારો પ્રથમ અહેવાલ સબમિટ કરો.", ur: "ابھی تک کچھ رجسٹر نہیں ہوا۔ بائیں طرف اپنی پہلی رپورٹ جمع کریں۔", kn: "ಇನ್ನೂ ಏನೂ ನೋಂದಾಯಿಸಿಲ್ಲ. ಎಡಭಾಗದಲ್ಲಿ ನಿಮ್ಮ ಮೊದಲ ವರದಿಯನ್ನು ಸಲ್ಲಿಸಿ.", or: "ଏପର୍ଯ୍ୟନ୍ତ କିଛି ପଞ୍ଜୀକୃତ ହୋଇନାହିଁ। ବାମ ପାର୍ଶ୍ୱରେ ଆପଣଙ୍କ ପ୍ରଥମ ରିପୋର୍ଟ ଦାଖଲ କରନ୍ତୁ।", ml: "ഇതുവരെ ഒന്നും രജിസ്റ്റർ ചെയ്തിട്ടില്ല. ഇടതുവശത്ത് നിങ്ങളുടെ ആദ്യ റിപ്പോർട്ട് സമർപ്പിക്കുക." },
  "lab.reportItem.labReportFallback": { en: "Lab report", hi: "लैब रिपोर्ट", bn: "ল্যাব রিপোর্ট", mr: "लॅब अहवाल", te: "ల్యాబ్ నివేదిక", ta: "ஆய்வக அறிக்கை", gu: "લેબ અહેવાલ", ur: "لیب رپورٹ", kn: "ಲ್ಯಾಬ್ ವರದಿ", or: "ଲ୍ୟାବ ରିପୋର୍ଟ", ml: "ലാബ് റിപ്പോർട്ട്" },
  "lab.reportItem.patientPrefix": { en: "Patient", hi: "मरीज़", bn: "রোগী", mr: "रुग्ण", te: "రోగి", ta: "நோயாளி", gu: "દર્દી", ur: "مریض", kn: "ರೋಗಿ", or: "ରୋଗୀ", ml: "രോഗി" },
  "lab.badge.registered": { en: "Registered", hi: "पंजीकृत", bn: "নিবন্ধিত", mr: "नोंदवले", te: "నమోదు చేయబడింది", ta: "பதிவு செய்யப்பட்டது", gu: "નોંધાયેલ", ur: "رجسٹرڈ", kn: "ನೋಂದಾಯಿಸಲಾಗಿದೆ", or: "ପଞ୍ଜୀକୃତ", ml: "രജിസ്റ്റർ ചെയ്തു" },
  "lab.error.attachFile": { en: "Attach the report file to register it.", hi: "इसे पंजीकृत करने के लिए रिपोर्ट फ़ाइल संलग्न करें।", bn: "নিবন্ধন করতে রিপোর্ট ফাইল সংযুক্ত করুন।", mr: "नोंदवण्यासाठी अहवाल फाइल जोडा.", te: "నమోదు చేయడానికి నివేదిక ఫైల్‌ను జోడించండి.", ta: "பதிவு செய்ய அறிக்கை கோப்பை இணைக்கவும்.", gu: "નોંધવા માટે અહેવાલ ફાઇલ જોડો.", ur: "رجسٹر کرنے کے لیے رپورٹ فائل منسلک کریں۔", kn: "ನೋಂದಾಯಿಸಲು ವರದಿ ಫೈಲ್ ಅನ್ನು ಲಗತ್ತಿಸಿ.", or: "ପଞ୍ଜୀକରଣ କରିବାକୁ ରିପୋର୍ଟ ଫାଇଲ ଯୋଡନ୍ତୁ।", ml: "രജിസ്റ്റർ ചെയ്യാൻ റിപ്പോർട്ട് ഫയൽ അറ്റാച്ച് ചെയ്യുക." },
  "lab.error.enterPatientId": { en: "Enter the patient ID this report belongs to.", hi: "यह रिपोर्ट जिस मरीज़ की है उसकी आईडी दर्ज करें।", bn: "এই রিপোর্টটি যে রোগীর তার আইডি লিখুন।", mr: "हा अहवाल ज्या रुग्णाचा आहे त्याचा आयडी टाका.", te: "ఈ నివేదిక ఏ రోగికి చెందినదో ఆ రోగి ఐడిని నమోదు చేయండి.", ta: "இந்த அறிக்கை சேர்ந்த நோயாளியின் எண்ணை உள்ளிடவும்.", gu: "આ અહેવાલ કયા દર્દીનો છે તેનો આઈડી દાખલ કરો.", ur: "وہ مریض آئی ڈی درج کریں جس کی یہ رپورٹ ہے۔", kn: "ಈ ವರದಿ ಯಾವ ರೋಗಿಗೆ ಸೇರಿದೆ ಎಂಬ ಐಡಿಯನ್ನು ನಮೂದಿಸಿ.", or: "ଏହି ରିପୋର୍ଟ କେଉଁ ରୋଗୀଙ୍କର ତାହାର ID ପ୍ରବେଶ କରାନ୍ତୁ।", ml: "ഈ റിപ്പോർട്ട് ഏത് രോഗിയുടേതാണെന്ന് ഐഡി നൽകുക." },
  "lab.notification.newResultPrefix": { en: "New", hi: "नया", bn: "নতুন", mr: "नवीन", te: "కొత్త", ta: "புதிய", gu: "નવું", ur: "نیا", kn: "ಹೊಸ", or: "ନୂଆ", ml: "പുതിയ" },
