  "patientInsurance.cardholder": { en: "Cardholder", hi: "कार्डधारक", bn: "কার্ডধারক", mr: "कार्डधारक", te: "కార్డుదారు", ta: "அட்டைதாரர்", gu: "કાર્ડધારક", ur: "کارڈ ہولڈر", kn: "ಕಾರ್ಡ್‌ದಾರ", or: "କାର୍ଡଧାରୀ", ml: "കാർഡ് ഉടമ" },
