  // Emergency view
  "emergencyView.subtitle": { en: "Blood group, allergies and contacts are shared instantly with responders on SOS", hi: "SOS पर रक्त समूह, एलर्जी और संपर्क तुरंत रिस्पॉन्डर्स के साथ साझा होते हैं", bn: "SOS-এ রক্তের গ্রুপ, অ্যালার্জি এবং যোগাযোগ তাৎক্ষণিকভাবে রেসপন্ডারদের সাথে শেয়ার হয়", mr: "SOS वर रक्तगट, ॲलर्जी आणि संपर्क त्वरित प्रतिसादकर्त्यांसोबत शेअर होतात", te: "SOSలో రక్త వర్గం, అలర్జీలు మరియు సంప్రదింపులు తక్షణమే రెస్పాండర్‌లతో పంచుకోబడతాయి", ta: "SOS இல் இரத்த வகை, ஒவ்வாமைகள் மற்றும் தொடர்புகள் உடனடியாக பதிலளிப்பாளர்களுடன் பகிரப்படும்", gu: "SOS પર બ્લડ ગ્રુપ, એલર્જી અને સંપર્કો તરત જ પ્રતિભાવકર્તાઓ સાથે શેર થાય છે", ur: "SOS پر بلڈ گروپ، الرجی اور رابطے فوری طور پر جواب دہندگان کے ساتھ شیئر ہوتے ہیں", kn: "SOS ನಲ್ಲಿ ರಕ್ತ ಗುಂಪು, ಅಲರ್ಜಿಗಳು ಮತ್ತು ಸಂಪರ್ಕಗಳನ್ನು ತಕ್ಷಣ ಪ್ರತಿಕ್ರಿಯಿಸುವವರೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಲಾಗುತ್ತದೆ", or: "SOS ରେ ରକ୍ତ ଗ୍ରୁପ, ଆଲର୍ଜି ଏବଂ ଯୋଗାଯୋଗ ତତ୍କ୍ଷଣାତ ପ୍ରତିକ୍ରିୟାକାରୀଙ୍କ ସହିତ ସେୟାର ହୁଏ", ml: "SOS ൽ രക്തഗ്രൂപ്പ്, അലർജികൾ, ബന്ധപ്പെടലുകൾ എന്നിവ തൽക്ഷണം പ്രതികരിക്കുന്നവരുമായി പങ്കിടുന്നു" },
  "emergencyView.sosTitle": { en: "Emergency SOS", hi: "आपातकालीन SOS", bn: "জরুরী SOS", mr: "आणीबाणी SOS", te: "అత్యవసర SOS", ta: "அவசர SOS", gu: "કટોકટી SOS", ur: "ہنگامی SOS", kn: "ತುರ್ತು SOS", or: "ଜରୁରୀକାଳୀନ SOS", ml: "അടിയന്തര SOS" },
  "emergencyView.sosDescription": { en: "Alerts your contacts and shares live location with the nearest ambulance", hi: "आपके संपर्कों को सचेत करता है और निकटतम एम्बुलेंस के साथ लाइव लोकेशन साझा करता है", bn: "আপনার যোগাযোগকে সতর্ক করে এবং নিকটতম অ্যাম্বুলেন্সের সাথে লাইভ অবস্থান শেয়ার করে", mr: "तुमच्या संपर्कांना सतर्क करते आणि जवळच्या रुग्णवाहिकेसह थेट स्थान शेअर करते", te: "మీ సంప్రదింపులను అప్రమత్తం చేస్తుంది మరియు సమీప అంబులెన్స్‌తో ప్రత్యక్ష స్థానాన్ని పంచుకుంటుంది", ta: "உங்கள் தொடர்புகளை எச்சரிக்கிறது மற்றும் அருகிலுள்ள ஆம்புலன்ஸுடன் நேரலை இருப்பிடத்தைப் பகிர்கிறது", gu: "તમારા સંપર્કોને ચેતવે છે અને નજીકની એમ્બ્યુલન્સ સાથે લાઇવ સ્થાન શેર કરે છે", ur: "آپ کے رابطوں کو خبردار کرتا ہے اور قریب ترین ایمبولینس کے ساتھ لائیو مقام شیئر کرتا ہے", kn: "ನಿಮ್ಮ ಸಂಪರ್ಕಗಳನ್ನು ಎಚ್ಚರಿಸುತ್ತದೆ ಮತ್ತು ಹತ್ತಿರದ ಆಂಬ್ಯುಲೆನ್ಸ್‌ನೊಂದಿಗೆ ನೇರ ಸ್ಥಳವನ್ನು ಹಂಚಿಕೊಳ್ಳುತ್ತದೆ", or: "ଆପଣଙ୍କ ଯୋଗାଯୋଗକୁ ସତର୍କ କରେ ଏବଂ ନିକଟତମ ଆମ୍ବୁଲାନ୍ସ ସହିତ ଲାଇଭ ଅବସ୍ଥାନ ସେୟାର କରେ", ml: "നിങ്ങളുടെ ബന്ധപ്പെടലുകളെ അലേർട്ട് ചെയ്യുകയും ഏറ്റവും അടുത്ത ആംബുലൻസുമായി ലൈവ് ലൊക്കേഷൻ പങ്കിടുകയും ചെയ്യുന്നു" },
  "emergencyView.toastSosSent": { en: "SOS sent, contacts alerted and nearest ambulance notified", hi: "SOS भेजा गया, संपर्कों को सचेत किया गया और निकटतम एम्बुलेंस को सूचित किया गया", bn: "SOS পাঠানো হয়েছে, যোগাযোগকে সতর্ক করা হয়েছে এবং নিকটতম অ্যাম্বুলেন্সকে জানানো হয়েছে", mr: "SOS पाठवले, संपर्कांना सतर्क केले आणि जवळच्या रुग्णवाहिकेला कळवले", te: "SOS పంపబడింది, సంప్రదింపులను అప్రమత్తం చేసి సమీప అంబులెన్స్‌కు తెలియజేయబడింది", ta: "SOS அனுப்பப்பட்டது, தொடர்புகள் எச்சரிக்கப்பட்டு அருகிலுள்ள ஆம்புலன்ஸ் அறிவிக்கப்பட்டது", gu: "SOS મોકલાયું, સંપર્કોને ચેતવ્યા અને નજીકની એમ્બ્યુલન્સને જાણ કરાઈ", ur: "SOS بھیج دیا گیا، رابطوں کو خبردار کیا گیا اور قریب ترین ایمبولینس کو مطلع کیا گیا", kn: "SOS ಕಳುಹಿಸಲಾಗಿದೆ, ಸಂಪರ್ಕಗಳನ್ನು ಎಚ್ಚರಿಸಲಾಗಿದೆ ಮತ್ತು ಹತ್ತಿರದ ಆಂಬ್ಯುಲೆನ್ಸ್‌ಗೆ ತಿಳಿಸಲಾಗಿದೆ", or: "SOS ପଠାହେଲା, ଯୋଗାଯୋଗକୁ ସତର୍କ କରାଗଲା ଏବଂ ନିକଟତମ ଆମ୍ବୁଲାନ୍ସକୁ ସୂଚିତ କରାଗଲା", ml: "SOS അയച്ചു, ബന്ധപ്പെടലുകളെ അലേർട്ട് ചെയ്തു, ഏറ്റവും അടുത്ത ആംബുലൻസിനെ അറിയിച്ചു" },
  "emergencyView.allergiesLabel": { en: "Allergies", hi: "एलर्जी", bn: "অ্যালার্জি", mr: "ॲलर्जी", te: "అలర్జీలు", ta: "ஒவ்வாமைகள்", gu: "એલર્જી", ur: "الرجی", kn: "ಅಲರ್ಜಿಗಳು", or: "ଆଲର୍ଜି", ml: "അലർജികൾ" },
